const dr=[_]i32{1,-1,1,-1,2,2,-2,-2};const dc=[_]i32{2,2,-2,-2,1,-1,1,-1};
fn search(b:*[25]i32,n:i32,r:i32,c:i32,step:i32)bool{if(step==n*n)return true;for(0..8)|k|{const nr=r+dr[k];const nc=c+dc[k];if(nr>=0 and nr<n and nc>=0 and nc<n){const at:usize=@intCast(nr*n+nc);if(b[at]==0){b[at]=step+1;if(search(b,n,nr,nc,step+1))return true;b[at]=0;}}}return false;}
fn put(outp:[*]u8,off:usize,x:i32)void{const bits:u32=@bitCast(x);for(0..4)|k|{outp[off+k]=@truncate(bits>>(8*k));}}
export fn open_knight_tour(v:?[*]const i64,n:usize,outp:?[*]u8,cap:usize)i64{const values=v orelse return -1;if(n!=1)return -1;const value=values[0];if(value!=1 and value!=5)return -1;const output=outp orelse return -2;const d:i32=@intCast(value);const bytes:usize=@intCast(d*d*4);if(cap<bytes)return -2;var b=[_]i32{0}**25;var found=false;outer:for(0..@as(usize,@intCast(d)))|r|{for(0..@as(usize,@intCast(d)))|c|{const at=r*@as(usize,@intCast(d))+c;b[at]=1;if(search(&b,d,@intCast(r),@intCast(c),1)){found=true;break :outer;}b[at]=0;}}_=found;for(0..@as(usize,@intCast(d*d)))|i|put(output,i*4,b[i]);return @intCast(bytes);}
